// @vitest-environment node
/**
 * Parity proof for the project board decided by astrid-core (AWTD-1585).
 *
 * board.json and statuses.json are generated by running this repo's own lib/project-status.ts and
 * lib/project-custom-states.ts (scripts/contract-fixtures/drivers/board.mjs, statuses.mjs) and
 * vendored at the pinned core revision. Every configuration's columns, every card's column and
 * every drop go through the TypeScript alone (the fallback) and with the vendored WebAssembly core
 * installed as the server installs it. Both must give the fixture's answer, and the core must have
 * answered every question itself. statuses.json has no rule of its own on the core's door, so each
 * board it produces — every add, rename, reorder and remove result — is drawn by both.
 */
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import { setBoardCore } from '@/lib/board-core-hook'
import { createBoardCore } from '@/lib/core-rules/board-core'
import { loadCoreRulesFrom } from '@/lib/core-rules/wasm'
import {
  getProjectBoardColumns,
  getTaskProjectColumnId,
  resolveProjectColumnCreate,
  resolveProjectColumnMove,
  type ProjectBoardColumn,
} from '@/lib/project-status'
import {
  addCustomState,
  removeCustomState,
  renameBuiltinState,
  renameCustomState,
  reorderCustomState,
} from '@/lib/project-custom-states'
import { DONE_COLUMN_ID, INBOX_COLUMN_ID, boardColumnsFor, isDefaultStatusRole, resolveColumnMove } from '@/lib/task-status'
import type { Task, TaskList } from '@/types/task'

const PACKAGE_DIR = path.join(process.cwd(), 'packages', 'astrid-rules')

type Move = { listIds: string[]; completed: boolean; statusRole: string | null }
interface BoardFixture {
  virtualInboxColumnId: string
  virtualDoneColumnId: string
  lists: Array<{ id: string; name: string; projectId: string | null; listType: string }>
  projectId: string
  domainTaskIds: string[]
  configurations: Array<{
    name: string
    customStates: unknown
    columns: ProjectBoardColumn[]
    cards: Array<{
      id: string
      completed: boolean
      statusRole: string | null
      listIds: string[]
      columnId: string
      moves: Array<{ columnId: string; result: Move }>
    }>
    creates: Array<{ columnId: string; withDomainList: object; withoutDomainList: object }>
  }>
}
interface StatusesFixture {
  boards: Record<string, unknown>
  cases: Array<{
    op: 'add' | 'rename' | 'reorder' | 'remove'
    board: string
    name?: string
    role?: string
    direction?: 'up' | 'down'
    result: { states?: unknown[]; error?: string }
  }>
}

const read = <T,>(file: string) => JSON.parse(readFileSync(file, 'utf8')) as T
const board = read<BoardFixture>(path.join(PACKAGE_DIR, 'fixtures', 'board.json'))
const statuses = read<StatusesFixture>(path.join(PACKAGE_DIR, 'fixtures', 'statuses.json'))
const core = loadCoreRulesFrom(PACKAGE_DIR)

const lists = board.lists as unknown as TaskList[]
const taskOf = (card: BoardFixture['configurations'][number]['cards'][number]) =>
  ({
    id: card.id,
    completed: card.completed,
    statusRole: card.statusRole,
    lists: card.listIds.map((id) => lists.find((list) => list.id === id)!),
  }) as unknown as Task

const configurations = board.configurations.map((c) => [c.name, c] as const)
const drops = board.configurations.flatMap((c) =>
  c.cards.flatMap((card) => card.moves.map((m) => [`${c.name}: ${card.id} → ${m.columnId}`, c, card, m] as const)),
)

/** lib/task-status.ts's names for the two virtual columns. */
const toTaskStatusId = (id: string) =>
  id === board.virtualInboxColumnId ? INBOX_COLUMN_ID : id === board.virtualDoneColumnId ? DONE_COLUMN_ID : id

function withCore() {
  const reports: unknown[] = []
  const hook = createBoardCore(core.runJson, { disagreement: (d) => reports.push(d), failure: (d) => reports.push(d) })
  setBoardCore({ columns: hook.columns, move: hook.move })
  return { hook, reports }
}

afterEach(() => setBoardCore(null))

describe('the board fixtures at the pinned core revision', () => {
  it('are the ones this repo exports — so the TypeScript, the fixture and the core are one chain', () => {
    // contracts/fixtures/*.json are checked against the TypeScript by check:contract-fixtures.
    expect(board).toEqual(read(path.join(process.cwd(), 'contracts', 'fixtures', 'board.json')))
    expect(statuses).toEqual(read(path.join(process.cwd(), 'contracts', 'fixtures', 'statuses.json')))
    expect(drops.length).toBeGreaterThanOrEqual(100)
  })
})

describe.each([
  ['the TypeScript alone (the fallback)', false],
  ['astrid-core answering, as the server runs it', true],
] as const)('%s', (_label, installed) => {
  const setup = () => (installed ? withCore() : null)
  const expectCoreAnswered = (installedCore: ReturnType<typeof setup>, questions: number) => {
    if (!installedCore) return
    expect(installedCore.reports).toEqual([])
    expect(installedCore.hook.stats).toEqual({ agreed: questions, disagreed: 0, skipped: 0, failed: 0 })
  }

  it.each(configurations)('columns: %s', (_name, configuration) => {
    const installedCore = setup()
    expect(getProjectBoardColumns(configuration.customStates)).toEqual(configuration.columns)
    // lib/task-status.ts draws the same board, naming the virtual columns its own way.
    expect(boardColumnsFor({ customStates: configuration.customStates })).toEqual(
      configuration.columns.map((column) => ({ ...column, id: toTaskStatusId(column.id) })),
    )
    expectCoreAnswered(installedCore, 2)
  })

  it.each(configurations)("each card's column: %s", (_name, configuration) => {
    const columns = getProjectBoardColumns(configuration.customStates)
    for (const card of configuration.cards) {
      expect(getTaskProjectColumnId(taskOf(card), columns), card.id).toBe(card.columnId)
    }
  })

  it.each(drops)('drop: %s', (_name, configuration, card, drop) => {
    const columns = getProjectBoardColumns(configuration.customStates)
    const column = columns.find((candidate) => candidate.id === drop.columnId)!
    const installedCore = setup()
    expect(resolveProjectColumnMove(taskOf(card), column, lists)).toEqual(drop.result)
    // The list row's planner writes the same status, and never touches memberships.
    expect(resolveColumnMove(card, toTaskStatusId(drop.columnId))).toEqual({
      statusRole: drop.result.statusRole,
      completed: drop.result.completed,
    })
    expectCoreAnswered(installedCore, 2)
  })

  it.each(configurations)('new cards: %s', (_name, configuration) => {
    const columns = getProjectBoardColumns(configuration.customStates)
    for (const create of configuration.creates) {
      const column = columns.find((candidate) => candidate.id === create.columnId)!
      const strip = (write: object) => JSON.parse(JSON.stringify(write))
      expect(strip(resolveProjectColumnCreate(column, 'domain-1'))).toEqual(create.withDomainList)
      expect(strip(resolveProjectColumnCreate(column, undefined))).toEqual(create.withoutDomainList)
    }
  })
})

describe("astrid-core's board, asked for its cards", () => {
  it.each(configurations)('puts every card in the fixture column: %s', (_name, configuration) => {
    const reply = JSON.parse(
      core.runJson(
        JSON.stringify({
          kind: 'board',
          projectId: board.projectId,
          customStates: configuration.customStates,
          lists: board.lists,
          // Done shows what finished recently; every card is stamped now, so the window holds them all.
          now: '2026-11-11T12:00:00.000Z',
          tasks: configuration.cards.map((card) => ({ ...card, updatedAt: '2026-11-11T11:00:00.000Z' })),
        }),
      ),
    ) as { ok: boolean; value: Array<{ id: string; taskIds: string[] }> }
    expect(reply.ok).toBe(true)
    const drawn = new Map(reply.value.flatMap((column) => column.taskIds.map((id) => [id, column.id] as const)))
    for (const card of configuration.cards) {
      // The board draws the project's cards only (board.json `domainTaskIds`).
      if (board.domainTaskIds.includes(card.id)) expect(drawn.get(card.id), card.id).toBe(card.columnId)
      else expect(drawn.has(card.id), card.id).toBe(false)
    }
  })
})

describe('statuses.json: every board the custom-state editor produces is drawn the same by both', () => {
  const rename = (raw: unknown, role: string, name: string) =>
    isDefaultStatusRole(role) ? renameBuiltinState(raw, role, name) : renameCustomState(raw, role, name)
  const run = (c: StatusesFixture['cases'][number]) => {
    const raw = statuses.boards[c.board]
    switch (c.op) {
      case 'add':
        return addCustomState(raw, c.name!)
      case 'rename':
        return rename(raw, c.role!, c.name!)
      case 'reorder':
        return reorderCustomState(raw, c.role!, c.direction!)
      case 'remove':
        return removeCustomState(raw, c.role!)
    }
  }
  const cases = statuses.cases.map((c, index) => [`${index} ${c.op} ${c.board} ${c.role ?? c.name ?? ''}`, c] as const)

  it.each(cases)('%s', (_name, c) => {
    expect(JSON.parse(JSON.stringify(run(c)))).toEqual(c.result)
    const boards = [statuses.boards[c.board], ...(c.result.states ? [c.result.states] : [])]
    for (const customStates of boards) {
      const typescript = getProjectBoardColumns(customStates)
      const { hook, reports } = withCore()
      expect(getProjectBoardColumns(customStates)).toEqual(typescript)
      expect(reports).toEqual([])
      expect(hook.stats.agreed).toBe(1)
      setBoardCore(null)
    }
  })
})
